import { useState } from 'react';
import {
  activeChips,
  CHIP_LABELS,
  withoutChip,
  ZONES,
  ZONE_LABELS,
  type ChipKey,
  type SearchCriteria,
  type Zone,
} from '../../lib/search';
import styles from './FilterChips.module.css';

/**
 * Chips de filtro activos + formulario `+ Filtro` de SRCH-01.
 *
 * Componente TOTALMENTE controlado: no guarda criterios, los recibe y emite
 * criterios nuevos enteros. El único estado propio es si el formulario inline
 * está abierto y lo que hay tecleado en él.
 *
 * `zone` y `country` comparten chip en `activeChips`; sin embargo, en el
 * formulario no se ofrece país a mano: el país lo rellena VERA. La zona sí,
 * porque son siete valores cerrados.
 */

interface FieldDef {
  key: ChipKey;
  label: string;
  type: 'text' | 'number' | 'zone';
}

const FIELDS: FieldDef[] = [
  { key: 'partNumber', label: CHIP_LABELS.partNumber, type: 'text' },
  { key: 'brand', label: CHIP_LABELS.brand, type: 'text' },
  { key: 'minQuantity', label: CHIP_LABELS.minQuantity, type: 'number' },
  { key: 'zone', label: CHIP_LABELS.zone, type: 'zone' },
  { key: 'maxLeadTimeDays', label: CHIP_LABELS.maxLeadTimeDays, type: 'number' },
];

interface Props {
  criteria: SearchCriteria;
  onChange: (next: SearchCriteria) => void;
}

export function FilterChips({ criteria, onChange }: Props) {
  const [formOpen, setFormOpen] = useState(false);
  const [field, setField] = useState<ChipKey | null>(null);
  const [value, setValue] = useState('');

  const openForm = () => {
    setField('partNumber');
    setValue('');
    setFormOpen(true);
  };

  const submit = () => {
    if (!field || value === '') return;

    if (field === 'minQuantity') {
      onChange({ ...criteria, minQuantity: Number(value) });
    } else if (field === 'maxLeadTimeDays') {
      onChange({ ...criteria, maxLeadTimeDays: Number(value) });
    } else if (field === 'zone') {
      onChange({ ...criteria, zone: (value as Zone) || null });
    } else if (field === 'partNumber') {
      onChange({ ...criteria, partNumber: value });
    } else if (field === 'brand') {
      onChange({ ...criteria, brand: value });
    }

    setField(null);
    setValue('');
    setFormOpen(false);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      submit();
    }
  };

  const fieldDef = FIELDS.find((f) => f.key === field) ?? null;

  return (
    <div className={styles.chipsRow} aria-label="Filtros de búsqueda">
      {activeChips(criteria).map((chip) => (
        <span key={chip.key} className={styles.chip}>
          <span className={styles.chipLabel}>{chip.label}</span>
          {chip.value}
          <button
            type="button"
            className={styles.chipX}
            aria-label={`Quitar filtro ${chip.label}`}
            title={`Quitar filtro ${chip.label}`}
            onClick={() => onChange(withoutChip(criteria, chip.key))}
          >
            ×
          </button>
        </span>
      ))}

      {formOpen ? (
        <form
          className={styles.form}
          onSubmit={(e) => {
            e.preventDefault();
            submit();
          }}
        >
          <select
            className={styles.fieldSelect}
            aria-label="Campo"
            value={field ?? ''}
            onChange={(e) => {
              const k = e.target.value as ChipKey;
              setField(k);
              setValue('');
            }}
          >
            {FIELDS.map((f) => (
              <option key={f.key} value={f.key}>
                {f.label}
              </option>
            ))}
          </select>

          {fieldDef?.type === 'zone' ? (
            <select
              className={styles.zoneSelect}
              aria-label="Valor"
              value={value}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={onKeyDown}
            >
              <option value="">Selecciona zona…</option>
              {ZONES.map((z) => (
                <option key={z} value={z}>
                  {ZONE_LABELS[z]}
                </option>
              ))}
            </select>
          ) : fieldDef?.type === 'number' ? (
            <input
              className={styles.valueInput}
              aria-label="Valor"
              type="number"
              min={0}
              step={1}
              value={value}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={onKeyDown}
            />
          ) : (
            <input
              className={styles.valueInput}
              aria-label="Valor"
              type="text"
              value={value}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={onKeyDown}
            />
          )}

          <button type="submit" className={styles.addBtn}>
            Añadir
          </button>
          <button
            type="button"
            className={styles.cancelBtn}
            aria-label="Cancelar filtro"
            onClick={() => {
              setFormOpen(false);
              setField(null);
              setValue('');
            }}
          >
            ×
          </button>
        </form>
      ) : (
        <button type="button" className={styles.chipAdd} onClick={openForm}>
          <i className="ti ti-plus" aria-hidden="true" />
          Filtro
        </button>
      )}
    </div>
  );
}

