import {
  ageLabel,
  countryName,
  daysSince,
  leadTimeLabel,
  meetsMinQuantity,
  quantityLabel,
  type SearchResultRow,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import styles from './ResultsTable.module.css';

/**
 * Tabla de resultados de SRCH-01 · diez columnas, selección múltiple y
 * ordenación por cabecera.
 *
 * Presentacional puro: pinta las filas EN EL ORDEN QUE LAS RECIBE (ordenar
 * es de la pantalla) y no carga datos. El estado vacío vive aquí, dentro de
 * la tabla, en su propia fila con `<td colSpan>` — en una `<table>` semántica
 * es ahí donde corresponde.
 *
 * La selección de todas las filas es responsabilidad de la metabarra de la
 * pantalla; esta tabla no duplica ese control en su cabecera.
 */

const SORTABLE: { column: SortColumn; label: string }[] = [
  { column: 'brand', label: 'Marca' },
  { column: 'quantity', label: 'Cantidad' },
  { column: 'leadTime', label: 'Plazo' },
  { column: 'country', label: 'País' },
  { column: 'age', label: 'Antigüedad' },
  { column: 'favorites', label: 'Favoritos' },
];

interface Props {
  rows: SearchResultRow[];
  sort: Sort | null;
  selected: ReadonlySet<string>;
  minQuantity: number | null;
  now?: Date;
  onSort: (column: SortColumn) => void;
  onToggleRow: (lineId: string) => void;
  onToggleFavorite: (orgId: string) => void;
  onConsult: (lineId: string) => void;
  onContact: (orgId: string) => void;
}

function SortableTh({
  column,
  label,
  sort,
  onSort,
}: {
  column: SortColumn;
  label: string;
  sort: Sort | null;
  onSort: (column: SortColumn) => void;
}) {
  const active = sort?.column === column;
  const direction = active ? sort!.direction : null;
  const ariaSort =
    active && direction
      ? direction === 'asc'
        ? ('ascending' as const)
        : ('descending' as const)
      : undefined;

  return (
    <th
      scope="col"
      aria-sort={ariaSort}
      className={
        active
          ? `${styles.sortable} ${direction === 'asc' ? styles.sortAsc : styles.sortDesc}`
          : styles.sortable
      }
    >
      <button type="button" className={styles.sortBtn} onClick={() => onSort(column)}>
        {label}
        {active && direction ? (direction === 'asc' ? ' ↑' : ' ↓') : ' ·'}
      </button>
    </th>
  );
}

export function ResultsTable({
  rows,
  sort,
  selected,
  minQuantity,
  now,
  onSort,
  onToggleRow,
  onToggleFavorite,
}: Props) {
  return (
    <div className={styles.outer}>
      <table className={styles.table}>
        <thead>
          <tr>
            <th scope="col" className={styles.thChk} aria-label="Selección" />
            <th scope="col">Referencia</th>

            <SortableTh
              column={SORTABLE[0].column}
              label={SORTABLE[0].label}
              sort={sort}
              onSort={onSort}
            />
            <SortableTh
              column={SORTABLE[1].column}
              label={SORTABLE[1].label}
              sort={sort}
              onSort={onSort}
            />
            <SortableTh
              column={SORTABLE[2].column}
              label={SORTABLE[2].label}
              sort={sort}
              onSort={onSort}
            />

            <th scope="col">Empresa</th>

            <SortableTh
              column={SORTABLE[3].column}
              label={SORTABLE[3].label}
              sort={sort}
              onSort={onSort}
            />
            <SortableTh
              column={SORTABLE[4].column}
              label={SORTABLE[4].label}
              sort={sort}
              onSort={onSort}
            />
            <SortableTh
              column={SORTABLE[5].column}
              label={SORTABLE[5].label}
              sort={sort}
              onSort={onSort}
            />

            <th scope="col" className={styles.thActions}>
              Acciones
            </th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={10} className={styles.emptyCell}>
                No hemos encontrado stock con estos filtros.
              </td>
            </tr>
          ) : (
            rows.map((row) => {
              const days = daysSince(row.lastUploadAt, now);
              const stale = days > 7;
              const qtyOk = meetsMinQuantity(row.quantity, minQuantity);
              const consultTitle = row.consulted
                ? 'Ya consultada anteriormente'
                : 'Selecciona esta fila y usa "Consultar seleccionados"';
              const contactTitle = 'Fuera del alcance de esta versión';

              return (
                <tr
                  key={row.id}
                  className={row.consulted ? styles.consultedRow : undefined}
                >
                  <td className={styles.tdChk}>
                    <input
                      type="checkbox"
                      className={styles.rowCheck}
                      aria-label={`Seleccionar ${row.partNumber} de ${row.orgName}`}
                      checked={selected.has(row.id)}
                      onChange={() => onToggleRow(row.id)}
                    />
                  </td>
                  <td>
                    <span className={styles.cellRef}>{row.partNumber}</span>
                  </td>
                  <td>
                    <span className={styles.badgeMarca}>{row.brand}</span>
                  </td>
                  <td>
                    <span className={qtyOk ? styles.cellQtyOk : styles.cellQtyLow}>
                      {quantityLabel(row.quantity)}
                    </span>
                  </td>
                  <td>
                    <span className={styles.cellPlazo}>{leadTimeLabel(row.leadTimeDays)}</span>
                  </td>
                  <td>
                    <span className={styles.cellEmpresa}>{row.orgName}</span>
                  </td>
                  <td>
                    <span className={styles.badgePais}>{countryName(row.country)}</span>
                  </td>
                  <td>
                    <span
                      className={
                        stale
                          ? `${styles.cellAntiguedad} ${styles.stale}`
                          : styles.cellAntiguedad
                      }
                    >
                      {ageLabel(days)}
                    </span>
                  </td>
                  <td>
                    <button
                      type="button"
                      className={styles.cellFav}
                      aria-pressed={row.isFavorite}
                      aria-label={`${row.isFavorite ? 'Quitar' : 'Marcar'} favorita a ${row.orgName} (${row.favoriteCount} favoritos)`}
                      onClick={() => onToggleFavorite(row.orgId)}
                    >
                      <span className={styles.favStar} aria-hidden="true">
                        {row.isFavorite ? '★' : '☆'}
                      </span>
                      <span>{row.favoriteCount}</span>
                    </button>
                  </td>
                  <td>
                    <div className={styles.actionsCell}>
                      <button
                        type="button"
                        className={styles.btnConsultar}
                        disabled
                        title={consultTitle}
                        aria-label={`Consultar ${row.partNumber}`}
                      >
                        Consultar
                      </button>
                      <button
                        type="button"
                        className={styles.btnContactar}
                        disabled
                        title={contactTitle}
                        aria-label={`Contactar ${row.orgName}`}
                      >
                        Contactar
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );
}

