import { useCallback, useEffect, useRef, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  consultSummary,
  EMPTY_CRITERIA,
  fetchResults,
  metaCounterLabel,
  nextSort,
  sortRows,
  toggleFavorite,
  type InquirySendResult,
  type SearchCriteria,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import { sendInquiries as sendInquiriesImpl } from '../../lib/thread-detail';
import { FilterChips } from './FilterChips';
import { ResultsTable } from './ResultsTable';
import styles from './SearchResults.module.css';

/**
 * La pantalla del panel de búsqueda (SRCH-01).
 *
 * Posee criterios, orden, selección, carga, error, favoritos y el envío de
 * consultas en lote. Ordena con `sortRows` antes de pasar las filas a la tabla.
 * `now` es inyectable para que los tests no dependan del reloj.
 */

interface InquiryItem {
  inventoryLineId: string;
  distributorOrgId: string;
  quantity: number;
}

const sendInquiries = sendInquiriesImpl as (
  orgId: string,
  items: InquiryItem[],
) => Promise<InquirySendResult[]>;

interface Props {
  profile: MemberProfile;
  now?: Date;
}

export function SearchResults({ profile, now }: Props) {
  const [criteria, setCriteria] = useState<SearchCriteria>(EMPTY_CRITERIA);
  const [sort, setSort] = useState<Sort | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [rows, setRows] = useState<Awaited<ReturnType<typeof fetchResults>>['rows']>([]);
  const [total, setTotal] = useState(0);
  const [capped, setCapped] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [consulting, setConsulting] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const consultingRef = useRef(false);

  const nowRef = now ?? new Date();

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchResults({ orgId: profile.orgId, memberId: profile.id, criteria })
      .then((page) => {
        if (cancelled) return;
        setRows(page.rows);
        setTotal(page.total);
        setCapped(page.capped);
      })
      .catch(() => {
        if (!cancelled) setError('No se pudieron cargar los resultados. Inténtalo de nuevo.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, profile.id, criteria, refreshKey]);

  /* Resultados nuevos → selección de la página anterior es basura. */
  useEffect(() => {
    setSelected(new Set());
    setNotice(null);
  }, [criteria]);

  const handleSort = useCallback((column: SortColumn) => {
    setSort((prev) => nextSort(prev, column));
  }, []);

  const toggleRow = useCallback((lineId: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(lineId)) {
        next.delete(lineId);
      } else {
        next.add(lineId);
      }
      return next;
    });
  }, []);

  const toggleAll = useCallback(() => {
    setSelected((prev) => {
      const allSelected = rows.length > 0 && rows.every((r) => prev.has(r.id));
      if (allSelected) return new Set();
      return new Set(rows.map((r) => r.id));
    });
  }, [rows]);

  const handleToggleFavorite = useCallback(
    async (orgId: string) => {
      const row = rows.find((r) => r.orgId === orgId);
      if (!row) return;
      try {
        await toggleFavorite(profile.id, orgId, !row.isFavorite);
        setRefreshKey((k) => k + 1);
      } catch {
        setError('No se pudieron actualizar los favoritos.');
      }
    },
    [rows, profile.id],
  );

  const handleConsultSelected = async () => {
    if (consultingRef.current) return;

    const selectedRows = rows.filter((r) => selected.has(r.id));
    const pending = selectedRows.filter((r) => !r.consulted);
    const omitidas = selectedRows.length - pending.length;

    consultingRef.current = true;
    setConsulting(true);

    try {
      if (pending.length === 0) {
        setNotice(consultSummary([], omitidas));
      } else {
        const resultados = await sendInquiries(
          profile.orgId,
          pending.map((r) => ({
            inventoryLineId: r.id,
            distributorOrgId: r.orgId,
            quantity: r.quantity,
          })),
        );
        setNotice(consultSummary(resultados, omitidas));
        setRefreshKey((k) => k + 1);
      }
    } catch {
      setNotice('No se pudieron enviar las consultas. Inténtalo de nuevo.');
    } finally {
      setSelected(new Set());
      consultingRef.current = false;
      setConsulting(false);
    }
  };

  const ordered = sortRows(rows, sort);
  const selectedCount = selected.size;
  const consultDisabled = selectedCount < 2 || consulting;
  const withStock =
    criteria.minQuantity === null
      ? rows.length
      : rows.filter((r) => r.quantity >= (criteria.minQuantity as number)).length;

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 03 · Búsqueda Conversacional</p>
      <h1 className={styles.title}>Resultados de búsqueda</h1>

      <div className={styles.resultsArea} aria-busy={loading ? 'true' : 'false'} aria-live="polite">
        <FilterChips criteria={criteria} onChange={setCriteria} />

        <div className={styles.metabar}>
          <p className={styles.metaCount}>
            <strong>{metaCounterLabel(total, withStock, criteria.minQuantity)}</strong>
          </p>
          <button
            type="button"
            className={styles.selAll}
            onClick={toggleAll}
            disabled={rows.length === 0}
          >
            {rows.length > 0 && rows.every((r) => selected.has(r.id))
              ? 'Deseleccionar todos'
              : 'Seleccionar todos'}
          </button>
          <button
            type="button"
            className={styles.consultSel}
            onClick={() => {
              void handleConsultSelected();
            }}
            disabled={consultDisabled}
          >
            Consultar seleccionados
          </button>
          <button
            type="button"
            className={styles.watcherBtn}
            disabled
            title="Crear watcher está fuera del alcance del MVP (SRCH-03, Plan §9)"
          >
            <i className="ti ti-bell-plus" aria-hidden="true" />
            Crear watcher con estos criterios
          </button>
        </div>

        {notice && (
          <p className={styles.notice} role="status">
            {notice}
          </p>
        )}

        {capped && (
          <p className={styles.capped}>
            Mostrando los primeros 200 resultados. Afina los filtros para verlos todos.
          </p>
        )}

        {error ? (
          <div className={styles.errorBox} role="alert">
            <p>{error}</p>
            <button
              type="button"
              className={styles.retryBtn}
              onClick={() => setRefreshKey((k) => k + 1)}
            >
              Reintentar
            </button>
          </div>
        ) : (
          <div className={styles.tableArea}>
            {loading && (
              <div className={styles.spinner} role="status" aria-label="Buscando resultados">
                <span aria-hidden="true" />
              </div>
            )}
            <ResultsTable
              rows={ordered}
              sort={sort}
              selected={selected}
              minQuantity={criteria.minQuantity}
              now={nowRef}
              onSort={handleSort}
              onToggleRow={toggleRow}
              onToggleFavorite={handleToggleFavorite}
              onConsult={() => {}}
              onContact={() => {}}
            />
          </div>
        )}
      </div>
    </div>
  );
}
